WITH products_by_supplier AS (SELECT supplier_id, ROUND((100 * SUM(CASE WHEN brand = 'Initech' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_initech FROM products GROUP BY supplier_id) SELECT s.country, s.city, pbs.pct_initech FROM suppliers s INNER JOIN products_by_supplier pbs ON s.id = pbs.supplier_id WHERE pbs.pct_initech > 48 ORDER BY country DESC;
